'use strict';
const $=id=>document.getElementById(id);
const money=value=>value===null||value===undefined?'Unknown':new Intl.NumberFormat(undefined,{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:Number(value)>0&&Number(value)<.01?6:2}).format(Number(value));
const when=value=>value?new Date(value).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'—';
const node=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=String(text);if(cls)e.className=cls;return e;};
let loadVersion=0;
async function api(path,options={}){const r=await fetch(path,{...options,credentials:'same-origin',headers:{'Accept':'application/json',...(options.headers||{})}});if(r.status===401){$('signin').hidden=false;$('dashboard').hidden=true;throw new Error('Sign in to view private records.');}if(!r.ok)throw new Error(`Unable to load records (${r.status}).`);return r.json();}
function paragraph(parent,text,cls){if(text)parent.append(node('p',text,cls));}
function action(parent,a){const box=node('article',undefined,'recommendation');box.append(node('strong',`${(a.action||a.code||'Recommendation').replaceAll('_',' ')} · ${a.target||a.subject||'Project'}`));paragraph(box,a.reason||a.detail);paragraph(box,a.proposed_action);if(a.evidence?.length){const d=node('details');d.append(node('summary','Evidence'));const ul=node('ul',undefined,'muted');for(const e of a.evidence)ul.append(node('li',typeof e==='string'?e:JSON.stringify(e)));d.append(ul);box.append(d);}parent.append(box);}
function review(parent,data){parent.replaceChildren();const r=data.report;const run=data.run||{};paragraph(parent,`${when(run.started_at)} · ${run.provider||r?.llm_review?.provider||'Deterministic'}${r?.llm_review?.model?' / '+r.llm_review.model:''}`,'muted');if(!r){paragraph(parent,'This run has no saved review report. Inspect its status and cost reservations before retrying.');return;}const llm=r.llm_review||{},assessment=llm.review;paragraph(parent,assessment?.summary||'This run contains a deterministic review of project activity.');if(llm.error)paragraph(parent,llm.error,'risks');const actions=assessment?.recommended_actions||r.findings||[];for(const a of actions)action(parent,a);if(!actions.length)paragraph(parent,'No action recommended. Wait for new evidence or spending.','muted');if(assessment?.risks?.length){const list=node('ul',undefined,'risks');for(const risk of assessment.risks)list.append(node('li',risk));parent.append(list);}if(assessment?.goal_assessment){const goals=node('div',undefined,'goals');for(const [id,title]of [['any_means','Walking by any effective means'],['rl_only','Walking learned only through RL']]){const goal=assessment.goal_assessment[id];if(!goal)continue;const el=node('article',undefined,'goal');el.append(node('strong',title));for(const [key,label]of [['sim','Simulation'],['physical','Physical robot'],['next_step','Next step']])paragraph(el,`${label}: ${goal[key]||'Unknown'}`);goals.append(el);}parent.append(goals);}if(r.source_errors?.length){const d=node('details');d.append(node('summary',`Source coverage (${r.source_errors.length} issues)`));for(const e of r.source_errors)paragraph(d,typeof e==='string'?e:(e.message||JSON.stringify(e)),'muted');parent.append(d);}paragraph(parent,`Actual cost: ${money(run.actual_cost_usd)} · Reserved: ${money(run.pending_reserved_usd)}`,'muted');}
async function showRun(id){$('run-detail').replaceChildren(node('p','Loading review…'));$('run-dialog').showModal();try{review($('run-detail'),await api('/api/runs/'+encodeURIComponent(id)));}catch(e){$('run-detail').replaceChildren(node('p',e.message));}}
async function refresh(){const version=++loadVersion;$('refresh').disabled=true;try{const [status,history,costs,recs]=await Promise.all(['/api/status','/api/runs','/api/costs','/api/recommendations'].map(p=>api(p)));if(version!==loadVersion)return;$('signin').hidden=true;$('dashboard').hidden=false;$('error').hidden=true;const b=costs.metaagent||status.budget||{};$('day-cost').textContent=money(b.rolling_24h_actual_usd);$('remaining').textContent=money(b.rolling_24h_remaining_usd);$('pending').textContent=money(b.pending_reserved_usd);$('project-cost').textContent=money(costs.monitored_total_usd);$('coverage').textContent=costs.unknown_cost_agents?`${costs.unknown_cost_agents} agents with unknown cost · ${money(costs.monitored_receipt_total_usd)} in receipts`:'Complete reported cost coverage';$('budget-meter').max=Number(b.daily_limit_usd||80);$('budget-meter').value=Number(b.rolling_24h_remaining_usd||0);$('updated').textContent='Updated '+when(status.generated_at);$('limits').textContent=`${money(b.wake_limit_usd)} per run · ${money(b.daily_limit_usd)} per rolling day`;
const runs=history.runs||[];$('run-count').textContent=`${runs.length} runs${history.truncated?' (newest shown)':''}`;$('runs').replaceChildren();$('empty-runs').hidden=runs.length>0;for(const run of runs){const tr=node('tr');for(const value of [when(run.started_at),run.model?`${run.provider||'Model'} / ${run.model}`:(run.provider||'See review'),run.outcome||run.status,money(run.actual_cost_usd),money(run.pending_reserved_usd)])tr.append(node('td',value));const td=node('td'),button=node('button','View');button.type='button';button.addEventListener('click',()=>showRun(run.wake_id));td.append(button);tr.append(td);$('runs').append(tr);}if(runs.length){$('latest-outcome').textContent=runs[0].outcome||runs[0].status;const latest=await api('/api/runs/'+encodeURIComponent(runs[0].wake_id));if(version!==loadVersion)return;review($('latest'),latest);}else{$('latest-outcome').textContent='No run yet';$('latest').replaceChildren(node('p','No review has run yet. Costs and recommendations will appear after the first manual run.','muted'));}
const open=(recs.recommendations||[]).filter(a=>!['resolved','declined'].includes(a.status));$('action-count').textContent=String(open.length);$('actions').replaceChildren();for(const a of open){action($('actions'),a.body||{});paragraph($('actions'),`${a.status} · Notification: ${a.notification_status||'not sent'}`,'muted');}if(!open.length)paragraph($('actions'),'No pending handoffs. Model recommendations remain attached to their review.','empty');const agents=costs.agents||[];$('agent-count').textContent=`· ${agents.length} records`;$('agents').replaceChildren();for(const a of agents){const tr=node('tr');for(const v of [a.name||a.agent_id,a.cost_status||'unknown',money(a.total_cost_usd),money(a.receipt_total_usd)])tr.append(node('td',v));$('agents').append(tr);}
}catch(e){$('error').textContent=e.message+' Existing values may be stale.';$('error').hidden=false;}finally{$('refresh').disabled=false;}}
$('refresh').addEventListener('click',refresh);$('close-dialog').addEventListener('click',()=>$('run-dialog').close());$('sso').href='https://hexapod.cwd1f0-new-cluster.coreweave.app/login?next='+encodeURIComponent(location.origin+'/');$('login').addEventListener('submit',async e=>{e.preventDefault();$('login-error').textContent='';try{await api('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:$('token').value})});$('token').value='';await refresh();}catch(error){$('login-error').textContent=error.message;}});refresh();
